    function autoGrowDebateTextarea(el) {
        if (!el) return;
        // Поле модератора на странице debate при закрытой ленте должно вести себя
        // как поле ввода на главной: растёт до 12 строк, а вместе с textarea
        // расширяется и весь .prompt-container (класс .is-prompt-autogrown снимает
        // фиксированную высоту 122px у композера и .mod-middle), иначе текст вылезает
        // за рамку. При открытой ленте контейнер высокий, рост идёт вверх (низ
        // зафиксирован) — поведение прежнее (кап 120px).
        const composer = el.id === 'modTa'
            ? el.closest('.prompt-container.prompt-sandwich.debate-composer')
            : null;
        const feedClosed = Boolean(composer) && !composer.classList.contains('has-debate-feed');
        if (feedClosed) {
            const cs = getComputedStyle(el);
            const lineHeight = parseFloat(cs.lineHeight) || (parseFloat(cs.fontSize) || 16) * 1.45;
            const padTop = parseFloat(cs.paddingTop) || 0;
            const padBottom = parseFloat(cs.paddingBottom) || 0;
            const maxH = lineHeight * 12 + padTop + padBottom;
            el.style.height = 'auto';
            const next = Math.min(el.scrollHeight, maxH);
            el.style.height = `${next}px`;
            el.style.overflowY = el.scrollHeight > maxH ? 'auto' : 'hidden';
            composer.classList.add('is-prompt-autogrown');
            return;
        }
        if (composer) composer.classList.remove('is-prompt-autogrown');
        el.style.overflowY = '';
        const max = 120;
        el.style.height = 'auto';
        el.style.height = `${Math.min(el.scrollHeight, max)}px`;
    }
